"import os
import math

def write_file(path, content):
    # Ensure directory exists
    dirname = os.path.dirname(path)
    if dirname:
        os.makedirs(dirname, exist_ok=True)
    with open(path, 'w') as f:
        f.write(content)

# -----------------------------------------------------------------------------
# 0/ Fields
# -----------------------------------------------------------------------------

# p_rgh: Pressure relative to hydrostatic
# We set p_rgh to 0 at the top wall (atmospheric) and gradient 0 elsewhere
write_file("0/p_rgh", """/*--------------------------------*- C++ -*----------------------------------*\\
| =========                 |                                                 |
| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |
|  \\\\    /   O peration     | Version:  10                                     |
|   \\\\  /    A nd           | Web:      www.OpenFOAM.org                      |
|    \\\\/     M anipulation  |                                                 |
\\*---------------------------------------------------------------------------*/
FoamFile
{
    version     2.0;
    format      ascii;
    class       volScalarField;
    object      p_rgh;
}
// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //

dimensions      [1 -1 -2 0 0 0 0];

internalField   uniform 0;

boundaryField
{
    bottom
    {
        type            fixedFluxPressure;
        gradient        uniform 0;
        value           uniform 0;
    }
    top
    {
        type            fixedValue;
        value           uniform 0;
    }
    front
    {
        type            fixedFluxPressure;
        gradient        uniform 0;
        value           uniform 0;
    }
    back
    {
        type            fixedFluxPressure;
        gradient        uniform 0;
        value           uniform 0;
    }
    left
    {
        type            fixedFluxPressure;
        gradient        uniform 0;
        value           uniform 0;
    }
    right
    {
        type            fixedFluxPressure;
        gradient        uniform 0;
        value           uniform 0;
    }
}

// ************************************************************************* //
""")

